#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    int longestBalancedSubarray(vector<int>& nums) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int pref = 0;
        int max_len = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            pref += (nums[i] % 2 == 0) ? 1 : -1;
            if (seen.count(pref)) {
                max_len = max(max_len, i - seen[pref]);
            } else {
                seen[pref] = i;
            }
        }
        return max_len;
    }
};

import java.util.*;

class Solution {
    public int longestBalancedSubarray(int[] nums) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, -1);
        int pref = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            pref += (nums[i] % 2 == 0) ? 1 : -1;
            if (seen.containsKey(pref)) {
                maxLen = Math.max(maxLen, i - seen.get(pref));
            } else {
                seen.put(pref, i);
            }
        }
        return maxLen;
    }
}

var longestBalancedSubarray = function(nums) {
    const seen = new Map();
    seen.set(0, -1);
    let pref = 0;
    let maxLen = 0;
    for (let i = 0; i < nums.length; i++) {
        pref += (nums[i] % 2 === 0) ? 1 : -1;
        if (seen.has(pref)) {
            maxLen = Math.max(maxLen, i - seen.get(pref));
        } else {
